UPDATE public.product_images SET is_shared = true, last_modified_source = 'claude', updated_at = now() WHERE canonical_image_id IS NOT NULL AND is_shared = false; WITH chains AS (SELECT pi1.id AS child_id, COALESCE(pi3.id, pi2.id) AS root_id FROM public.product_images pi1 JOIN public.product_images pi2 ON pi2.id = pi1.canonical_image_id LEFT JOIN public.product_images pi3 ON pi3.id = pi2.canonical_image_id WHERE pi1.canonical_image_id IS NOT NULL AND pi2.canonical_image_id IS NOT NULL) UPDATE public.product_images pi SET canonical_image_id = c.root_id, last_modified_source = 'claude', updated_at = now() FROM chains c WHERE pi.id = c.child_id AND pi.id <> c.root_id;;
